import{_ as t,o as d,c as o,aj as r}from"./chunks/framework.DdvcgEK0.js";const u=JSON.parse('{"title":"Upgrading from v1","description":"","frontmatter":{},"headers":[],"relativePath":"guide/migration.md","filePath":"guide/migration.md"}'),a={name:"guide/migration.md"};function c(i,e,n,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="upgrading-from-v1" tabindex="-1">Upgrading from v1 <a class="header-anchor" href="#upgrading-from-v1" aria-label="Permalink to &quot;Upgrading from v1&quot;">​</a></h1><p>v2 is a rewrite: fewer functions, flat options, stable return types and a smarter default score.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>v1</th><th>v2</th></tr></thead><tbody><tr><td><code>rate(a, b)</code>, <code>getSimilarityScore(a, b)</code></td><td><code>similarity(a, b)</code></td></tr><tr><td><code>rate(a, b, { explain: true })</code></td><td><code>compare(a, b)</code></td></tr><tr><td><code>isMatch(a, b, 85)</code></td><td>unchanged</td></tr><tr><td><code>findBestMatch(q, list)</code></td><td><code>closest(q, list)</code>, returns <code>undefined</code> below the threshold</td></tr><tr><td><code>rankCandidates(q, list)</code></td><td><code>search(q, list, { threshold: 0 })</code></td></tr><tr><td><code>filterMatches(q, list)</code></td><td><code>search(q, list).map((m) =&gt; m.item)</code></td></tr><tr><td><code>extract(q, list, { limit })</code></td><td><code>search(q, list, { limit }).map((m) =&gt; m.item)</code></td></tr><tr><td><code>createMatcher(options)</code></td><td>unchanged, with more methods</td></tr><tr><td><code>normalize</code>, <code>normalizeString</code></td><td><code>normalize</code></td></tr><tr><td><code>getLevenshteinDistance</code></td><td><code>levenshtein</code></td></tr><tr><td><code>getJaroWinklerScore(a, b)</code></td><td><code>jaroWinkler(a, b) * 100</code></td></tr></tbody></table><p>List results are now <code>{ item, score, index, text }</code> (<code>value</code> became <code>item</code>).</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><p>Options are flat: the <code>normalize: { ... }</code> block is gone.</p><table tabindex="0"><thead><tr><th>v1</th><th>v2</th></tr></thead><tbody><tr><td><code>algorithm: &#39;hybrid&#39;</code></td><td>default <code>smart</code></td></tr><tr><td><code>spaceInsensitive: true</code></td><td>default (<code>ignoreSpaces: true</code>)</td></tr><tr><td><code>normalize.sortTokens: true</code></td><td>default (<code>ignoreWordOrder: true</code>)</td></tr><tr><td><code>normalize.caseSensitive</code></td><td><code>caseSensitive</code></td></tr><tr><td><code>normalize.removeAccents: false</code></td><td><code>accentSensitive: true</code></td></tr><tr><td><code>normalize.removePunctuation: false</code></td><td><code>punctuation: &#39;keep&#39;</code></td></tr><tr><td><code>normalize.punctuationStrategy</code></td><td><code>punctuation: &#39;space&#39; | &#39;remove&#39;</code></td></tr><tr><td><code>normalize.replacements</code></td><td><code>replace</code> (whole words only)</td></tr><tr><td><code>normalize.removeWords</code></td><td><code>ignoreWords</code></td></tr><tr><td><code>return: &#39;entries&#39;</code>, <code>explain</code> on lists</td><td>always entries; use <code>compare()</code> to explain</td></tr></tbody></table><h2 id="scores" tabindex="-1">Scores <a class="header-anchor" href="#scores" aria-label="Permalink to &quot;Scores&quot;">​</a></h2><p><code>smart</code> tolerates swapped letters, word order and missing spaces, so similar texts generally score higher than with v1&#39;s <code>levenshtein</code>. Re-check thresholds on a few real examples with <code>compare()</code>.</p><h2 id="behavior-fixes" tabindex="-1">Behavior fixes <a class="header-anchor" href="#behavior-fixes" aria-label="Permalink to &quot;Behavior fixes&quot;">​</a></h2><ul><li><code>replace</code> used to replace inside words (<code>st → saint</code> turned <code>stairs</code> into <code>saintairs</code>). It now replaces whole words only.</li><li>Two texts made only of punctuation used to score 100. An empty guess is now always <code>wrong</code> in <code>check()</code>.</li><li>Non-string inputs (<code>null</code>, <code>undefined</code>, numbers) no longer throw: they are read as text.</li></ul>',12)])])}const p=t(a,[["render",c]]);export{u as __pageData,p as default};
